    if not cols:
        _qfos_acct_ensure_snapshot_table(cur)
        cols = _qfos_acct_table_columns(cur, "portfolio_snapshots")

    values = {}
    if "equity" in cols:
        values["equity"] = equity
    if "cash" in cols:
        values["cash"] = cash
    if "exposure" in cols:
        values["exposure"] = exposure
    if "drawdown" in cols:
        values["drawdown"] = drawdown
    if "regime" in cols:
        values["regime"] = regime
    if "created_at" in cols:
