def _qfos_v2_upsert_feature_snapshot(features):
    if not QFOS_POLICY_V2_ENABLED:
        return
    if not isinstance(features, dict):
        return

    import sqlite3
    conn = sqlite3.connect(_qfos_v2_db_path(), timeout=10)
