        """, rows)

        conn.commit()

        if rows:
            print(f"[POLICY_V2] feature_snapshot_upserted count={len(rows)}", flush=True)

    except Exception as exc:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"[POLICY_V2] feature_snapshot_error={exc}", flush=True)
    finally:
        try:
