    is_exit = normalized_fill.get("is_exit")
    exit_reason = normalized_fill.get("exit_reason")

    if not is_exit:
        raise RuntimeError(
            "SELL_ACCOUNTING_INVARIANT_FAIL:is_exit_false:%s"
